import MaterialIcons from "@expo/vector-icons/MaterialIcons";
import * as ImagePicker from "expo-image-picker";
import { useEffect, useMemo, useState } from "react";
import { ActivityIndicator, Alert, Image, Pressable, ScrollView, StyleSheet, Switch, Text, TextInput, TouchableOpacity, View } from "react-native";
import { router } from "expo-router";
import { ScreenContainer } from "@/components/screen-container";
import { djangoApi } from "@/lib/django-api";

type Item=Record<string,unknown>;
type Section={id:number;title:string;section_type:"hero"|"banner"|"category"|"product_grid"|"trend";config:Item;sort_order:number;is_visible:boolean};
type Category={id:number;name:string;slug:string};
const MAX_IMAGE_CHARS=520000;
const TYPES=[{id:"hero",title:"واجهة رئيسية",icon:"view-carousel",hint:"صورة كبيرة"},{id:"banner",title:"بانرات",icon:"image",hint:"عروض وصور"},{id:"category",title:"الفئات",icon:"category",hint:"تصنيفات المتجر"},{id:"product_grid",title:"المنتجات",icon:"grid-view",hint:"شبكة المنتجات"},{id:"trend",title:"الترند",icon:"local-fire-department",hint:"الأكثر رواجًا"}] as const;
function list<T>(v:unknown):T[]{return Array.isArray(v)?v as T[]:[]}
async function chooseImage():Promise<string>{const r=await ImagePicker.launchImageLibraryAsync({mediaTypes:["images"],allowsEditing:false,quality:0.25,base64:true,exif:false});const a=r.assets?.[0];if(r.canceled||!a?.base64)return "";const data=`data:${(a.mimeType??"image/jpeg").toLowerCase()};base64,${a.base64}`;if(data.length>MAX_IMAGE_CHARS){Alert.alert("الصورة كبيرة جدًا","تم منع الإرسال حتى لا يظهر خطأ 413. اختر صورة أصغر.");return ""}return data}
export default function VendorStorefrontScreen(){
 const [sections,setSections]=useState<Section[]>([]);const [categories,setCategories]=useState<Category[]>([]);const [selected,setSelected]=useState<number|null>(null);const [draft,setDraft]=useState<Item>({});const [loading,setLoading]=useState(true);const [saving,setSaving]=useState(false);
 const current=useMemo(()=>selected==null?null:sections.find(s=>s.id===selected)??null,[sections,selected]);
 async function load(){try{setLoading(true);const [a,b]=await Promise.all([djangoApi<{results?:Section[]}>("/api/storefront-sections/"),djangoApi<{results?:Category[]}>("/api/categories/")]);setSections((a.results??[]).sort((x,y)=>x.sort_order-y.sort_order));setCategories(b.results??[])}catch(e){Alert.alert("تعذر تحميل المصمم",e instanceof Error?e.message:"حدث خطأ أثناء التحميل.")}finally{setLoading(false)}}
 useEffect(()=>{void load()},[]);
 function open(s:Section){setSelected(s.id);setDraft({...s.config,title:s.title,is_visible:s.is_visible})}
 async function save(next:dItem){if(!current)return;setSaving(true);try{const payload={title:String(next.title??current.title),section_type:current.section_type,is_visible:Boolean(next.is_visible),config:Object.fromEntries(Object.entries(next).filter(([k])=>!['title','is_visible','section_type'].includes(k)))};const result=await djangoApi<Section>(`/api/storefront-sections/${current.id}/`,{method:"PATCH",body:JSON.stringify(payload)});setSections(old=>old.map(s=>s.id===result.id?result:s));setDraft({...result.config,title:result.title,is_visible:result.is_visible});Alert.alert("تم الحفظ","تم تحديث واجهة المتجر.")}catch(e){Alert.alert("تعذر الحفظ",e instanceof Error?e.message:"تعذر حفظ التغييرات.")}finally{setSaving(false)}}
 async function create(type:Section["section_type"]){const config=type==="category"?{published:true,mode:"automatic",category_circles:[]}:type==="product_grid"||type==="trend"?{published:true,source:type==="trend"?"trending":"latest",rows:2,columns:2,scroll:true,show_categories:true}:{published:true,slides:[]};try{const result=await djangoApi<Section>("/api/storefront-sections/",{method:"POST",body:JSON.stringify({title:TYPES.find(x=>x.id===type)?.title??"قسم جديد",section_type:type,config,sort_order:sections.length,is_visible:true})});setSections(old=>[...old,result].sort((a,b)=>a.sort_order-b.sort_order));open(result)}catch(e){Alert.alert("تعذر إضافة القسم",e instanceof Error?e.message:"تحقق من صلاحيات حساب التاجر.")}}
 async function addBanner(){const image=await chooseImage();if(!image)return;const slides=list<Item>(draft.slides);await save({...draft,slides:[...slides,{id:`slide-${Date.now()}`,title:"عرض جديد",subtitle:"",ctaLabel:"تسوّق الآن",url:"",imageUrl:image,visible:true,sortOrder:slides.length}]})}
 async function addCategory(){if(!categories.length){Alert.alert("لا توجد فئات","أضف الفئات من إدارة الكتالوج أولًا.");return}const buttons=categories.slice(0,12).map(c=>({text:c.name,onPress:async()=>{const image=await chooseImage();if(!image)return;const circles=list<Item>(draft.category_circles);await save({...draft,category_circles:[...circles,{id:`circle-${Date.now()}`,category_id:c.id,title:c.name,targetCategory:c.slug,url:`/collection?category=${encodeURIComponent(c.slug)}`,imageUrl:image,visible:true,sortOrder:circles.length}]})}}));Alert.alert("اختر الفئة","اختر فئة ثم أضف صورتها.",buttons)}
 async function remove(){if(selected==null)return;try{setSaving(true);await djangoApi(`/api/storefront-sections/${selected}/`,{method:"DELETE"});setSections(old=>old.filter(s=>s.id!==selected));setSelected(null);setDraft({})}catch(e){Alert.alert("تعذر الحذف",e instanceof Error?e.message:"لا يمكن حذف القسم الآن.")}finally{setSaving(false)}}
 if(loading)return <ScreenContainer><View style={s.center}><ActivityIndicator size="large" color="#E60023"/><Text style={s.muted}>نجهّز مساحة التصميم...</Text></View></ScreenContainer>;
 return <ScreenContainer className="bg-[#F3F4F6]"><ScrollView contentContainerStyle={s.page}><View style={s.header}><TouchableOpacity style={s.icon} onPress={()=>router.back()}><MaterialIcons name="arrow-forward" size={23} color="#111"/></TouchableOpacity><View style={s.headCopy}><Text style={s.headTitle}>مصمم واجهة المتجر</Text><Text style={s.headSub}>أضف الأقسام والصور ورتب واجهتك كما تريد</Text></View></View><View style={s.hero}><View style={s.heroIcon}><MaterialIcons name="dashboard-customize" size={22} color="#FFF"/></View><View style={s.heroCopy}><Text style={s.heroTitle}>ابنِ واجهة متجرك</Text><Text style={s.heroText}>كل تغيير تحفظه يظهر في المتجر العام بعد النشر.</Text></View></View><Text style={s.sectionTitle}>إضافة قسم</Text><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={s.types}>{TYPES.map(t=><Pressable key={t.id} style={s.type} onPress={()=>create(t.id)}><View style={s.typeIcon}><MaterialIcons name={t.icon as any} size={21} color="#E60023"/></View><Text style={s.typeTitle}>{t.title}</Text><Text style={s.typeHint}>{t.hint}</Text></Pressable>)}</ScrollView><View style={s.sectionHeader}><Text style={s.sectionTitle}>أقسام المتجر</Text><Text style={s.muted}>{sections.length} أقسام</Text></View>{sections.map((item,index)=><View key={item.id} style={[s.card,selected===item.id&&s.selected]}><View style={s.cardTop}><View style={s.cardIcon}><MaterialIcons name={(TYPES.find(x=>x.id===item.section_type)?.icon??"view-module") as any} size={19} color="#E60023"/></View><View style={s.cardCopy}><Text style={s.cardTitle}>{item.title}</Text><Text style={s.cardMeta}>{TYPES.find(x=>x.id===item.section_type)?.title??item.section_type} • {index+1}</Text></View><Switch value={item.is_visible} onValueChange={v=>{setSections(old=>old.map(x=>x.id===item.id?{...x,is_visible:v}:x));djangoApi(`/api/storefront-sections/${item.id}/`,{method:"PATCH",body:JSON.stringify({is_visible:v})}).catch(()=>void load())}}/></View><View style={s.actions}><TouchableOpacity style={s.action} onPress={()=>open(item)}><MaterialIcons name="edit" size={16} color="#111"/><Text style={s.actionText}>تحرير</Text></TouchableOpacity><TouchableOpacity style={s.delete} onPress={()=>{setSelected(item.id);setDraft({...item.config,title:item.title,is_visible:item.is_visible});Alert.alert("حذف القسم","سيتم حذف هذا القسم من واجهة المتجر.",[{text:"إلغاء",style:"cancel"},{text:"حذف",style:"destructive",onPress:()=>remove()}])}}><MaterialIcons name="delete-outline" size={16} color="#B42318"/><Text style={s.deleteText}>حذف</Text></TouchableOpacity></View></View>)}{current&&<View style={s.editor}><Text style={s.editorTitle}>تحرير القسم</Text><TextInput value={String(draft.title??"")} onChangeText={v=>setDraft(x=>({...x,title:v}))} style={s.input} textAlign="right" placeholder="عنوان القسم"/><View style={s.visibility}><Text style={s.visibilityText}>إظهار للعملاء</Text><Switch value={Boolean(draft.is_visible)} onValueChange={v=>setDraft(x=>({...x,is_visible:v}))}/></View>{(current.section_type==="hero"||current.section_type==="banner")&&<><TouchableOpacity style={s.mediaButton} onPress={addBanner} disabled={saving}><MaterialIcons name="add-photo-alternate" size={20} color="#E60023"/><Text style={s.mediaText}>{saving?"جارٍ حفظ الصورة...":"إضافة صورة أو بانر"}</Text></TouchableOpacity>{list<Item>(draft.slides).map((slide,i)=><View key={String(slide.id??i)} style={s.mediaItem}>{slide.imageUrl?<Image source={{uri:String(slide.imageUrl)}} style={s.thumb}/>:<View style={s.thumb}/> }<View style={s.mediaCopy}><TextInput value={String(slide.title??"")} onChangeText={v=>setDraft(x=>({...x,slides:list<Item>(x.slides).map((z,n)=>n===i?{...z,title:v}:z)}))} style={s.smallInput} textAlign="right"/><TouchableOpacity onPress={()=>setDraft(x=>({...x,slides:list<Item>(x.slides).filter((_,n)=>n!==i)}))}><Text style={s.deleteText}>حذف البانر</Text></TouchableOpacity></View></View>)}</>}{current.section_type==="category"&&<><TouchableOpacity style={s.mediaButton} onPress={addCategory}><MaterialIcons name="add-photo-alternate" size={20} color="#E60023"/><Text style={s.mediaText}>إضافة فئة وصورتها</Text></TouchableOpacity></> }<TouchableOpacity style={s.save} onPress={()=>save(draft)} disabled={saving}>{saving?<ActivityIndicator color="#FFF"/>:<Text style={s.saveText}>حفظ ونشر التغييرات</Text>}</TouchableOpacity></View>}</ScrollView></ScreenContainer>
}
type dItem=Item;
const s=StyleSheet.create({center:{flex:1,alignItems:"center",justifyContent:"center",padding:30},page:{padding:12,paddingBottom:100},header:{backgroundColor:"#FFF",borderRadius:16,padding:12,flexDirection:"row-reverse",alignItems:"center",gap:10},icon:{width:40,height:40,borderRadius:12,backgroundColor:"#F3F3F4",alignItems:"center",justifyContent:"center"},headCopy:{flex:1,alignItems:"flex-end"},headTitle:{fontSize:18,fontWeight:"900",color:"#111"},headSub:{fontSize:9,color:"#888",marginTop:2},hero:{marginTop:10,backgroundColor:"#15171B",borderRadius:18,padding:14,flexDirection:"row-reverse",alignItems:"center",gap:10},heroIcon:{width:44,height:44,borderRadius:13,backgroundColor:"#E60023",alignItems:"center",justifyContent:"center"},heroCopy:{flex:1,alignItems:"flex-end"},heroTitle:{color:"#FFF",fontSize:17,fontWeight:"900"},heroText:{color:"#CDD0D5",fontSize:10,marginTop:3,textAlign:"right"},sectionTitle:{fontSize:15,fontWeight:"900",color:"#171717",marginTop:14,marginBottom:8,textAlign:"right"},types:{gap:8},type:{width:105,backgroundColor:"#FFF",borderWidth:1,borderColor:"#E7E7E9",borderRadius:14,padding:9,alignItems:"center"},typeIcon:{width:36,height:36,borderRadius:10,backgroundColor:"#FFF0F3",alignItems:"center",justifyContent:"center"},typeTitle:{fontSize:10,fontWeight:"900",marginTop:5,color:"#222"},typeHint:{fontSize:8,color:"#888",marginTop:2},sectionHeader:{flexDirection:"row-reverse",alignItems:"baseline",justifyContent:"space-between"},muted:{fontSize:10,color:"#888"},card:{backgroundColor:"#FFF",borderRadius:14,borderWidth:1,borderColor:"#E8E8EA",padding:10,marginBottom:8},selected:{borderColor:"#E60023"},cardTop:{flexDirection:"row-reverse",alignItems:"center",gap:9},cardIcon:{width:38,height:38,borderRadius:11,backgroundColor:"#FFF0F3",alignItems:"center",justifyContent:"center"},cardCopy:{flex:1,alignItems:"flex-end"},cardTitle:{fontSize:12,fontWeight:"900",color:"#222"},cardMeta:{fontSize:8,color:"#888",marginTop:2},actions:{flexDirection:"row-reverse",gap:7,marginTop:8},action:{flexDirection:"row-reverse",gap:4,paddingHorizontal:9,paddingVertical:7,borderRadius:9,backgroundColor:"#F5F5F6"},actionText:{fontSize:9,fontWeight:"800"},delete:{flexDirection:"row-reverse",gap:4,paddingHorizontal:8,paddingVertical:7},deleteText:{fontSize:9,fontWeight:"800",color:"#B42318"},editor:{backgroundColor:"#FFF",borderRadius:16,padding:12,marginTop:10},editorTitle:{fontSize:15,fontWeight:"900",color:"#111",textAlign:"right",marginBottom:8},input:{height:45,backgroundColor:"#F7F7F8",borderWidth:1,borderColor:"#E2E2E5",borderRadius:10,paddingHorizontal:11,color:"#111"},visibility:{marginTop:8,backgroundColor:"#F8F8F9",borderRadius:10,padding:9,flexDirection:"row-reverse",alignItems:"center",justifyContent:"space-between"},visibilityText:{fontSize:10,fontWeight:"800",color:"#222"},mediaButton:{height:45,borderWidth:1,borderStyle:"dashed",borderColor:"#E60023",borderRadius:10,marginTop:8,flexDirection:"row-reverse",alignItems:"center",justifyContent:"center",gap:6,backgroundColor:"#FFF7F9"},mediaText:{fontSize:10,fontWeight:"900",color:"#B2173E"},mediaItem:{marginTop:7,padding:7,borderRadius:10,backgroundColor:"#FAFAFB",flexDirection:"row-reverse",alignItems:"center",gap:8},thumb:{width:78,height:46,borderRadius:8,backgroundColor:"#EEE"},mediaCopy:{flex:1,alignItems:"flex-end"},smallInput:{width:"100%",height:38,borderWidth:1,borderColor:"#E2E2E5",borderRadius:8,paddingHorizontal:8,fontSize:10},save:{height:48,borderRadius:13,marginTop:12,backgroundColor:"#E60023",alignItems:"center",justifyContent:"center"},saveText:{color:"#FFF",fontSize:11,fontWeight:"900"}})